int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int d[61] = {0}, e[61] = {0};

    for (int i = 0; i < n; i++) {
        int m;
        char l;
        scanf("%d %c", &m, &l);

        if (l == 'D') {
            d[m]++;
